		"[--noheadings] [--nosuffix] [--separator <separator>]\n\t"
		"[--units <units>]\n\t"
		"[<device>...]\n\n",
		_base_commands[_base_command].name);

	fprintf(out, "<device> may be device name.\n"
		"<fields> are comma-separated.  Use 'help -c' for list.\n\n");
}

